sed -i '/composable("playlist_details\/{id}"/i \            composable("video_player/{uri}", arguments = listOf(navArgument("uri") { type = NavType.StringType })) {\n                val uri = it.arguments?.getString("uri") ?: ""\n                VideoPlayerScreen(uriString = java.net.URLDecoder.decode(uri, "UTF-8"), onNavigateBack = { navController.popBackStack() })\n            }' app/src/main/java/com/example/ui/AppNavigation.kt
sed -i 's/0 -> VideoScreen(viewModel)/0 -> VideoScreen(viewModel, onNavigateToVideoPlayer = { uri -> navController.navigate("video_player\/${java.net.URLEncoder.encode(uri, "UTF-8")}") })/g' app/src/main/java/com/example/ui/screens/MainScreen.kt
